    "styles.css": `/*
 * Portfolio Grid - Refined Academic Grid Layout
 * Clean, organized presentation with subtle sophistication
 * Inspired by architectural portfolios and modern editorial design
 */

@import url('https://fonts.googleapis.com/css2?family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Work+Sans:wght@300;400;500;600&display=swap');

:root {
    --color-navy: #2c3e50;
    --color-slate: #546e7a;
    --color-sage: #7a9e9f;
    --color-cream: #faf8f5;
    --color-stone: #e8e4df;
    --color-charcoal: #3a3a3a;
    --color-mist: #90a4ae;

    --font-serif: 'Libre Baskerville', Georgia, serif;
    --font-sans: 'Work Sans', -apple-system, sans-serif;

    --spacing-unit: 8px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-sans);
    line-height: 1.6;
    color: var(--color-charcoal);
    background: var(--color-cream);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

::selection {
    background: var(--color-sage);
    color: white;
}

/* Header */
header {
    padding: calc(var(--spacing-unit) * 10) calc(var(--spacing-unit) * 4) calc(var(--spacing-unit) * 8);
    background: linear-gradient(to bottom, var(--color-navy) 0%, #3d5a6b 100%);
    color: var(--color-cream);
    position: relative;
    overflow: hidden;
}

header::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: linear-gradient(to right, transparent 0%, var(--color-sage) 50%, transparent 100%);
}

header h1 {
    font-family: var(--font-serif);
    font-size: clamp(2.5rem, 6vw, 4rem);
    font-weight: 400;
    margin-bottom: calc(var(--spacing-unit) * 2);
    letter-spacing: -0.01em;
    opacity: 0;
    animation: fadeInUp 0.8s ease 0.2s forwards;
}

header p {
    font-size: 1rem;
    font-weight: 300;
    letter-spacing: 0.03em;
    opacity: 0.85;
    max-width: 600px;
    animation: fadeInUp 0.8s ease 0.4s forwards;
    opacity: 0;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Container */
.container {
    max-width: 1400px;
    margin: 0 auto;
    padding: calc(var(--spacing-unit) * 8) calc(var(--spacing-unit) * 4);
}

/* Grid */
.grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
    gap: calc(var(--spacing-unit) * 5);
    opacity: 0;
    animation: fadeIn 0.6s ease 0.5s forwards;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

/* Project Cards */
.project-card {
    background: white;
    border: 1px solid var(--color-stone);
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
}

.project-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--color-sage);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.project-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
    border-color: var(--color-sage);
}

.project-card:hover::before {
    transform: scaleX(1);
}

.project-card img {
    width: 100%;
    height: 320px;
    object-fit: cover;
    display: block;
    filter: grayscale(0.15) contrast(1.02);
    transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.project-card:hover img {
    filter: grayscale(0) contrast(1.05);
    transform: scale(1.03);
}

/* Project Info */
.project-info {
    padding: calc(var(--spacing-unit) * 4);
    position: relative;
}

.project-info h2 {
    font-family: var(--font-serif);
    font-size: 1.5rem;
    font-weight: 400;
    margin-bottom: calc(var(--spacing-unit) * 1.5);
    color: var(--color-navy);
    letter-spacing: -0.01em;
    transition: color 0.3s ease;
}

.project-card:hover .project-info h2 {
    color: var(--color-sage);
}

.project-info p {
    color: var(--color-slate);
    line-height: 1.7;
    font-size: 0.9375rem;
    font-weight: 300;
}

/* Footer */
footer {
    text-align: center;
    padding: calc(var(--spacing-unit) * 8) calc(var(--spacing-unit) * 4);
    background: var(--color-navy);
    color: var(--color-stone);
    margin-top: calc(var(--spacing-unit) * 8);
    position: relative;
}

footer::before {
    content: '';
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 60px;
    height: 2px;
    background: var(--color-sage);
}

footer p {
    font-size: 0.875rem;
    font-weight: 300;
    letter-spacing: 0.02em;
}

footer a {
    color: var(--color-sage);
    text-decoration: none;
    font-weight: 400;
    transition: color 0.3s ease;
    position: relative;
}

footer a::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 100%;
    height: 1px;
    background: currentColor;
    transform: scaleX(0);
    transform-origin: right;
    transition: transform 0.3s ease;
}

footer a:hover {
    color: var(--color-cream);
}

footer a:hover::after {
    transform: scaleX(1);
    transform-origin: left;
}

/* Responsive */
@media (max-width: 768px) {
    header {
        padding: calc(var(--spacing-unit) * 8) calc(var(--spacing-unit) * 3) calc(var(--spacing-unit) * 6);
    }

    .container {
        padding: calc(var(--spacing-unit) * 6) calc(var(--spacing-unit) * 3);
    }

    .grid {
        grid-template-columns: 1fr;
        gap: calc(var(--spacing-unit) * 4);
    }

    .project-info {
        padding: calc(var(--spacing-unit) * 3);
    }

    .project-info h2 {
        font-size: 1.375rem;
    }
}

/* Focus Visibility */
a:focus-visible {
    outline: 2px solid var(--color-sage);
    outline-offset: 3px;
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    .project-card:hover,
    .project-card:hover img {
        transform: none;
    }
}
`
