    "styles.css": `/*
 * Portfolio Magazine - Contemporary Editorial Layout
 * Sophisticated magazine-inspired design for academic work
 * Balanced typography with refined visual hierarchy
 */

@import url('https://fonts.googleapis.com/css2?family=Crimson+Pro:ital,wght@0,300;0,400;0,600;1,400&family=Inter:wght@300;400;500;600&display=swap');

:root {
    --color-ink: #1a1a1a;
    --color-graphite: #4a4a4a;
    --color-pewter: #6b7280;
    --color-paper: #ffffff;
    --color-linen: #f9fafb;
    --color-accent: #7c6f5f;
    --color-accent-light: #a89884;
    --color-border: #e5e7eb;

    --font-serif: 'Crimson Pro', 'Georgia', serif;
    --font-sans: 'Inter', -apple-system, sans-serif;

    --space: 8px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-sans);
    font-weight: 400;
    line-height: 1.6;
    color: var(--color-ink);
    background: var(--color-linen);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

::selection {
    background: var(--color-accent);
    color: white;
}

/* Hero Section */
.hero {
    background: var(--color-ink);
    color: var(--color-paper);
    padding: clamp(6rem, 15vw, 12rem) calc(var(--space) * 4) clamp(4rem, 10vw, 8rem);
    text-align: left;
    border-bottom: 1px solid var(--color-graphite);
    position: relative;
}

.hero::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: calc(var(--space) * 4);
    width: 80px;
    height: 3px;
    background: var(--color-accent);
}

.hero-content {
    max-width: 1200px;
    margin: 0 auto;
}

.hero-content h1 {
    font-family: var(--font-serif);
    font-size: clamp(3rem, 8vw, 6rem);
    font-weight: 400;
    margin-bottom: calc(var(--space) * 3);
    letter-spacing: -0.02em;
    line-height: 1.1;
    opacity: 0;
    animation: fadeSlideUp 0.8s ease 0.2s forwards;
}

@keyframes fadeSlideUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.hero-content p {
    font-size: clamp(1rem, 2vw, 1.125rem);
    font-weight: 300;
    letter-spacing: 0.01em;
    opacity: 0.85;
    max-width: 640px;
    animation: fadeSlideUp 0.8s ease 0.4s forwards;
    opacity: 0;
}

/* Container */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: clamp(4rem, 8vw, 7rem) calc(var(--space) * 4);
    background: var(--color-paper);
}

/* Feature Articles */
.feature {
    margin-bottom: clamp(6rem, 12vw, 10rem);
    opacity: 0;
    animation: fadeIn 0.8s ease forwards;
}

.feature:nth-child(1) { animation-delay: 0.2s; }
.feature:nth-child(2) { animation-delay: 0.35s; }
.feature:nth-child(3) { animation-delay: 0.5s; }

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.feature-image {
    margin-bottom: calc(var(--space) * 4);
    overflow: hidden;
    border: 1px solid var(--color-border);
    background: var(--color-linen);
    transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.feature-image:hover {
    border-color: var(--color-accent);
}

.feature-image img {
    width: 100%;
    height: auto;
    display: block;
    filter: contrast(1.02);
    transition: all 0.7s cubic-bezier(0.4, 0, 0.2, 1);
}

.feature:hover .feature-image img {
    transform: scale(1.02);
    filter: contrast(1.05);
}

.category {
    display: inline-block;
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    color: var(--color-accent);
    font-weight: 600;
    padding: calc(var(--space) * 1) calc(var(--space) * 2);
    margin-bottom: calc(var(--space) * 2);
    text-transform: uppercase;
    border: 1px solid var(--color-accent);
    transition: all 0.3s ease;
}

.category:hover {
    background: var(--color-accent);
    color: white;
}

.feature-content h2 {
    font-family: var(--font-serif);
    font-size: clamp(2rem, 5vw, 3.25rem);
    line-height: 1.2;
    margin-bottom: calc(var(--space) * 2);
    color: var(--color-ink);
    font-weight: 400;
    letter-spacing: -0.015em;
    position: relative;
    padding-left: calc(var(--space) * 3);
}

.feature-content h2::before {
    content: '';
    position: absolute;
    left: 0;
    top: calc(var(--space) * 1);
    width: 4px;
    height: calc(100% - calc(var(--space) * 2));
    background: var(--color-accent);
    transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.feature:hover .feature-content h2::before {
    width: 6px;
}

.excerpt {
    font-family: var(--font-serif);
    font-size: clamp(1.125rem, 2vw, 1.25rem);
    line-height: 1.7;
    color: var(--color-graphite);
    margin-bottom: calc(var(--space) * 2.5);
    font-weight: 300;
    padding-left: calc(var(--space) * 3);
}

.meta {
    font-size: 0.875rem;
    color: var(--color-pewter);
    font-weight: 400;
    letter-spacing: 0.02em;
    padding-left: calc(var(--space) * 3);
}

/* Works Grid */
.works-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: clamp(3rem, 5vw, 4rem);
    margin-top: calc(var(--space) * 6);
}

.work-item {
    transition: transform 0.3s ease;
}

.work-item:hover {
    transform: translateY(-6px);
}

.work-item img {
    width: 100%;
    height: 320px;
    object-fit: cover;
    border: 1px solid var(--color-border);
    margin-bottom: calc(var(--space) * 2);
    display: block;
    transition: all 0.4s ease;
    filter: grayscale(0.1);
}

.work-item:hover img {
    filter: grayscale(0);
    border-color: var(--color-accent);
}

.work-content h3 {
    font-family: var(--font-serif);
    font-size: clamp(1.375rem, 3vw, 1.625rem);
    line-height: 1.3;
    margin-bottom: calc(var(--space) * 1.5);
    color: var(--color-ink);
    font-weight: 600;
    letter-spacing: -0.01em;
}

.work-content p {
    font-size: 0.9375rem;
    color: var(--color-graphite);
    line-height: 1.6;
    font-weight: 300;
}

/* Footer */
footer {
    text-align: center;
    padding: calc(var(--space) * 8) calc(var(--space) * 4);
    background: var(--color-ink);
    color: var(--color-linen);
    border-top: 3px solid var(--color-accent);
}

footer a {
    color: var(--color-accent-light);
    text-decoration: none;
    font-weight: 500;
    margin: 0 calc(var(--space) * 2);
    font-size: 0.9375rem;
    letter-spacing: 0.02em;
    position: relative;
    display: inline-block;
    padding: calc(var(--space) * 1) 0;
    transition: color 0.3s ease;
}

footer a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 1px;
    background: currentColor;
    transform: scaleX(0);
    transform-origin: right;
    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

footer a:hover {
    color: var(--color-paper);
}

footer a:hover::after {
    transform: scaleX(1);
    transform-origin: left;
}

/* Responsive */
@media (max-width: 768px) {
    .hero {
        padding: 5rem calc(var(--space) * 3);
    }

    .hero::after {
        left: calc(var(--space) * 3);
        width: 60px;
    }

    .container {
        padding: calc(var(--space) * 6) calc(var(--space) * 3);
    }

    .feature {
        margin-bottom: 5rem;
    }

    .feature-content h2 {
        padding-left: calc(var(--space) * 2);
    }

    .excerpt,
    .meta {
        padding-left: calc(var(--space) * 2);
    }

    .works-grid {
        grid-template-columns: 1fr;
        gap: calc(var(--space) * 5);
    }

    .work-item img {
        height: 260px;
    }

    footer a {
        display: block;
        margin: calc(var(--space) * 2) 0;
    }
}

/* Focus Visibility */
a:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    html {
        scroll-behavior: auto;
    }

    .work-item:hover,
    .feature:hover .feature-image img {
        transform: none;
    }
}
`
